drills.solution:
const amountOk = (c) => Number.isInteger(c) && c > 0;

export class Account {
  #balance = 0;

  constructor(owner) {
    this.owner = owner;
  }

  deposit(cents) {
    if (!amountOk(cents)) throw new RangeError('deposit must be a positive whole number of cents');
    this.#balance += cents;
    return this;
  }

  withdraw(cents) {
    if (!amountOk(cents)) throw new RangeError('withdrawal must be a positive whole number of cents');
    if (cents > this.#balance) throw new RangeError('insufficient funds');
    this.#balance -= cents;
    return this;
  }

  get balance() {
    return this.#balance;
  }

  toJSON() {
    return { owner: this.owner, balance: this.#balance };
  }

  static fromJSON(data) {
    const a = new Account(data.owner);
    if (data.balance > 0) a.deposit(data.balance);
    return a;
  }
}

tests.code:
const a = new mod.Account('ana');
for (const bad of [0, -5, 2.5, NaN]) assert.throws(() => a.deposit(bad), RangeError, `deposit(${bad})`);
assert.throws(() => a.withdraw(0), RangeError);
assert.equal(a.balance, 0);

const a = new mod.Account('ana').deposit(100);
assert.throws(() => a.withdraw(101), RangeError);
assert.equal(a.balance, 100);
assert.equal(a.withdraw(100).balance, 0);

const a = new mod.Account('ana').deposit(50);
assert.deepEqual(Object.keys(a), ['owner']);
assert.equal(Object.getOwnPropertyDescriptor(a, 'balance'), undefined);

const a = new mod.Account('bo').deposit(750);
const json = JSON.parse(JSON.stringify(a));
assert.deepEqual(json, { owner: 'bo', balance: 750 });
const b = mod.Account.fromJSON(json);
assert.ok(b instanceof mod.Account);
assert.equal(b.balance, 750);
assert.equal(b.owner, 'bo');

drills.explanation:
A `#balance` field holds the state; every mutation goes through methods that validate first:

```js
withdraw(cents) {
  if (!amountOk(cents)) throw new RangeError('withdrawal must be a positive whole number of cents');
  if (cents > this.#balance) throw new RangeError('insufficient funds');
  this.#balance -= cents;
  return this;
}
```

`amountOk` needs `Number.isInteger`, not just `c > 0`: with the shorter check `deposit(2.5)` is accepted and the test "bad amounts throw RangeError" fails. The overdraft guard must be `>`, not `>=`, or withdrawing the whole balance is refused and "overdrawing throws and leaves the balance alone (boundary)" fails. Because `#balance` is private, `JSON.stringify` would drop it; without `toJSON` the output is `{ owner }` only, and "toJSON / fromJSON round-trip" fails. `fromJSON` rebuilds through `deposit`, so a restored balance passes the same validation.

